  `update_by_id` smallint(6) NULL DEFAULT NULL,
  `update_ip` varchar(15) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL,
  `delete_date` datetime NULL DEFAULT NULL,
  `delete_by_id` smallint(6) NULL DEFAULT NULL,
  `delete_ip` varchar(15) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`quotation_id`) USING BTREE,
  INDEX `idx_production_id`(`production_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 179 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

