INSERT INTO `production_task` VALUES (284, 31, 11, 'Additional Request (ดูรายละเอียดใน ASANA)', 'Production Cost: เอา total rate ออก\r\nเลข jobno ต้องไม่ซ้ำกัน\r\nProduction Cost: Format name - Client: [client]:[project name]\r\nProduction Cost ต้องกลับมา save อีกครั้ง ถ้ามีการแก้ไข estimate\r\nEstimate: ใส่ duration ให้หน่อยครับ\r\nEstimate: เรียงตามตัวอักษร\r\nEstimate : แสดงผลเป็น [member_name]-[team_name] และเรียง team_name\r\n\r\nจำการ filter\r\nแก้ไขข้อความใน alert message เมื่อกดปุ่ม copy \r\nEstimated: .ให้มี Hint ที่ icon ว่ามี action อะไร\r\nEstimated: เลือก filter แล้ว icon copy หาย\r\nไม่ใส่ pm แล้ว error\r\n\r\nFix 2019-09-05\r\nClone Estimated Cost ไม่ต้อง Auto สร้าง Quotation \r\nเพิ่มการ Sync ชื่อ ระหว่าง Estimated กับ Production Cost ด้วย\r\nเพิ่ม Status Close ที่ Production Cost \r\nProduction Cost ที่เปลี่ยน Status เป็น  Approved และ Close แล้ว ห้ามแก้ไข รวมทั้งห้ามแก้ Estimated ที่เกี่ยวข้องด้วย\r\nQuotation ที่อ้างถึง Production Cost เอาเฉพาะที่มี status Approved และ Close\r\nQuotation เมื่อสร้างใหม่แล้วเลือก Production Cost แล้วตัวเลขที่แสดง ไม่มี Comma\r\n', 7.00, 18, 'active', 'N', 'Y', '2019-10-07 19:32:03', 3, '171.96.192.2', NULL, NULL, NULL, NULL, NULL, NULL);
