INSERT INTO `production_task` VALUES (287, 31, 10, 'เพิ่มสถานะเอกสาร Close', 'Production Cost เปลี่ยนสถานะ Close\r\n- Lock ห้ามแก้ Estimated, Production Cost , Quotation ที่เกี่ยวข้องกัน\r\nQuotation เปลี่ยนสถานะ Close\r\n- ถ้าเป็น Quotation เปลี่ยนเป็น Close ได้ถ้าเป็น Quotation  ที่ไม่ได้อ้างอิง Production Cost', 7.00, 18, 'active', 'Y', 'N', '2020-04-15 17:41:39', 3, '184.22.234.230', NULL, NULL, NULL, NULL, NULL, NULL);
