INSERT INTO `production_task` VALUES (674, 103, 2, 'Get Influencer Info', '1. สร้างฐานข้อมูลตามที่ออกแบบมา\r\n2. สร้างตัว config file สำหรับ ปรับเปลี่ยนเมื่อต้องนำไปใช้งานจริง\r\n3. connect ฐานข้อมูล motive เพื่อดึงข้อมูลของ influencer และ connect เพื่อดูรูปจาก mongodb \r\n4. บันทึก transaction ของ influencer กับฐานข้อมูลที่ได้สร้างขึ้นมาใหม่', 11.00, 16, 'active', 'Y', 'N', '2020-05-25 14:21:11', 1, '171.96.205.74', NULL, NULL, NULL, NULL, NULL, NULL);
