INSERT INTO `production_task` VALUES (677, 100, 3, 'เปลี่ยนการ Register | Sign In Instagram โดยใช้ Graph API', 'เปลี่ยนการใช้ API ของ Instagram มาใช้ Facebook Graph\r\nเพิ่มการเก็บและแสดงข้อมูล Friends ของ Facebook\r\nเพิ่มการเก็บและแสดงข้อมูล Posts ของ Facebook\r\nขอสิทธิ์ user_friends, user_posts, instagram_basic,manage_pages จาก Facebook\r\n\r\nเก็บข้อมูล Profile และ Posts Stat Instagram จาก Graph API โดยดึงจาก Facebook Page ที่ผูกกับ Instagram \r\nแสดงข้อมูล Instagram ที่ Influencer เลือกจากการ Authenticate และให้  User เลือก Instagram Account ที่ต้องการเข้าร่วม Motive Influence\r\n\r\n', 40.00, 12, 'active', 'Y', 'N', '2020-10-16 14:48:26', 1, '124.122.56.156', NULL, NULL, NULL, NULL, NULL, NULL);
