INSERT INTO `production_task` VALUES (972, 152, 1, 'ใช้ Point แลกเงิน - Redeem (12)', 'ถ้าเลือกสินค้าที่แลกเป็นเงิน แล้ว ห้ามมีแลกสินค้ารวมด้วย   is_cash = \'Y\'\r\nตรวจสอบเอกสารการรับเงิน (ตัวอย่างจากหน้า Campaign ที่รับเป็นเงิน)\r\nเก็บข้อมูลเอกสารใน Redeem ด้วย\r\n\r\nเพิ่ม Field\r\n\r\nALTER TABLE `influencer_redeem`\r\nADD COLUMN `influencer_citizenid`  varchar(13) NULL AFTER `redeem_no`,\r\nADD COLUMN `influencer_name_citizenidcard`  varchar(150) NULL AFTER `influencer_citizenid`,\r\nADD COLUMN `influencer_image_citizenidcard`  varchar(300) NULL AFTER `influencer_name_citizenidcard`,\r\nADD COLUMN `influencer_image_bookbank`  varchar(300) NULL AFTER `influencer_image_citizenidcard`,\r\nADD COLUMN `is_cash`  enum(\'Y\',\'N\') NULL DEFAULT \'N\' AFTER `influencer_image_bookbank`;\r\n\r\nALTER TABLE `influencer_redeem_detail`\r\nADD COLUMN `reward_iscash`  enum(\'Y\',\'N\') NOT NULL DEFAULT \'N\' AFTER `reward_value`;', 12.00, 18, 'active', 'Y', 'N', '2020-10-16 15:14:20', 1, '124.122.56.156', NULL, NULL, NULL, NULL, NULL, NULL);
