INSERT INTO `production_task` VALUES (1348, 204, 1, 'Motive Influence Artwork for Sep 2020', 'Blog\r\n1. MKT: การมี AI ช่วยในการหาคนที่เหมาะสม ช่วยให้หาคนตรงกับ campaign ได้ยังไงบ้าง  - ภาพประกอบเนื้อหา 2 ชิ้น\r\n2. MKT: Natural Sharer - Banner 3 ชิ้น\r\n3. วัด ROI ในการทำ Influencer Marketing อย่างมีประสิทธิภาพ  3 ชิ้น\r\n4. 5 เหตุผลที่นักการตลาดควรรู้ Audience ของอินฟลูเอนเซอร์  3 ชิ้น\r\n\r\nSingle Photo\r\n5. Influencer Marketing News 1 ชิ้น\r\n6. ทำไมธุรกิจต้องใช้ Influencer Marketing  1 ชิ้น\r\n7. 3 เทคนิคทำวิดีโอสั้นให้สนุก (infographic) 1 ชิ้น\r\n\r\nPhoto Album\r\n8. เปิดสูตรการเป็น Influencer มือโปร 5 ชิ้น\r\n', 0.00, 28, 'active', 'Y', 'N', '2020-09-17 14:42:41', 1, '110.168.174.206', NULL, NULL, NULL, NULL, NULL, NULL);
