INSERT INTO `quotations_detail` VALUES (114, 16, 2, 'Campaign Detail - เอกสารสัญญา Approved/ Disapproved', 'แสดงเอกสารสัญญา ให้ User เห็นในระบบกรณีที่มีการเซ็นเอกสารในแคมเปญ เมื่อทำการ Approved หรือ Disapproved แล้ว\r\nเพิ่มการแสดงเหตุผลเมื่อ Disapproved แสดงเอกสารสัญญา', 0, 0.00, 0.00, 'active', 'Y', 'N', '2019-09-05 10:55:38', 3, '115.87.227.184', NULL, NULL, NULL, NULL, NULL, NULL);
