INSERT INTO `quotations_detail` VALUES (116, 16, 4, '[CMS] Prepost Export', 'แสดงรายชื่อผู้เข้าร่วม Campaign และ เลือกคนที่จะ export งานได้\r\nprepost export ในแต่ละครั้งในกรองเฉพาะคนที่อยู่ในสถานะ prepost sended เท่านั้น', 0, 0.00, 0.00, 'active', 'Y', 'N', '2019-09-05 10:55:38', 3, '115.87.227.184', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `quotations_detail` VALUES (117, 16, 5, 'Campaign Detail - ส่งรูป Prepost', 'ปรับระบบ browse รูปให้น้อง motive สามารถbrowse รูปเพื่อส่งงานทีเดียว 10 รูปได้\r\nบางครั้ง browse 10 จะขึ้นรูปแค่ 5 รูป เนื่องจากรูปที่ส่งมีขนาดใหญ่ และ อาจเกิด Timeout หรือ Net หลุดได้', 0, 0.00, 0.00, 'active', 'Y', 'N', '2019-09-05 10:55:38', 3, '115.87.227.184', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `quotations_detail` VALUES (118, 16, 6, '[CMS] report-withholding-tax', 'ทำเป็น PDF file เหมือนตัวแลกของรางวัล\r\n(หัก ณ ที่จ่ายแลกของรางวัลคำนวณแบบการออกภาษีให้ (จำนวนสินค้า*100/97) ทำเหมือนการจ่ายเงินเป็นไฟล์ PDF ออกในระบบ ได้หรือไม่ จะได้ไม่ต้องมานั่งแก้ไขไฟล์ Excel )', 0, 0.00, 0.00, 'active', 'Y', 'N', '2019-09-05 10:55:38', 3, '115.87.227.184', NULL, NULL, NULL, NULL, NULL, NULL);
