INSERT INTO `quotations_detail` VALUES (121, 16, 9, '[CMS] System Config', 'แยกค่า Configuration ตามประเทศที่ Influencer ได้ลงทะเบียนไว้\r\nPoint for Apply\r\nPoint for Referral\r\nMinimum Apply -  Instagram / Facebook / Facebook Page / Twitter / Youtube\r\nMotive Plus minimum reach\r\nMinimum Post for Statistic\r\nFraud Check (Influencer)\r\nWithholding Tax', 0, 0.00, 0.00, 'active', 'Y', 'N', '2019-09-05 10:55:38', 3, '115.87.227.184', NULL, NULL, NULL, NULL, NULL, NULL);
