INSERT INTO `quotations_detail` VALUES (194, 23, 6, '[CMS] report-withholding-tax', 'ทำเป็น PDF file เหมือนตัวแลกของรางวัล\r\n(หัก ณ ที่จ่ายแลกของรางวัลคำนวณแบบการออกภาษีให้ (จำนวนสินค้า*100/97) ทำเหมือนการจ่ายเงินเป็นไฟล์ PDF ออกในระบบ ได้หรือไม่ จะได้ไม่ต้องมานั่งแก้ไขไฟล์ Excel )', 0, 0.00, 0.00, 'active', 'Y', 'N', '2019-12-11 12:22:43', 6, '171.96.195.182', NULL, NULL, NULL, NULL, NULL, NULL);
