INSERT INTO `quotations_detail` VALUES (279, 30, 2, 'Fix การเก็บข้อมูล Stat ของ Random Instagram', 'แยกการ random follower และการเก็บ stat และ รูป Profile ออกจากกัน\r\nการเก็บรูป Profile ใช้การทำงานผ่าน ftp เพื่อแยกเก็บจากหลาย Server\r\nแก้ไขการเก็บ Stat scrape instagram page โดยใช้ Cookie ของ account instagram\r\nการทำงานทั้งหมดถูกย้ายไปเข้าระบบที่มีตัวกลางในการจัดการการเรียกใช้', 0, 0.00, 0.00, 'active', 'Y', 'N', '2020-01-10 18:30:55', 6, '119.76.162.63', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `quotations_detail` VALUES (280, 30, 3, 'เพิ่มการเก็บข้อมูล System ID. ของ Line - หน้า Profile', '- เพิ่มขั้นตอนการ Login ด้วย Line เพื่อเก็บ  System ID. ของ Line สำหรับใช้ในการติดต่อโดยใช้ line@\r\n- ตรวจสอบการ add line@ ของ motive influence และ  ต้อง add line@ ด้วย\r\n- สำหรับผู้สมัครใหม่ ขั้นตอนนี้บังคับให้ทุกคนต้องทำ ก่อนที่จะไป Verify และ Approve ต่อไป ', 0, 0.00, 0.00, 'active', 'Y', 'N', '2020-01-10 18:30:55', 6, '119.76.162.63', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `quotations_detail` VALUES (281, 30, 4, 'เพิ่มการเก็บข้อมูล System ID. ของ Line - หน้า Campaign', '- การเข้าร่วม Campaign เพิ่มขั้นตอนการ Login ด้วย Line เพื่อเก็บ  System ID. ของ Line สำหรับใช้ในการติดต่อโดยใช้ line@\r\nสำหรับผู้สมัครที่ยังไม่ข้อมูล  System ID. ของ Line\r\n- ตรวจสอบการ add line@ ของ motive influence และ  ต้อง add line@ ด้วย\r\n- ขั้นตอนนี้บังคับให้ทุกคนต้องทำ ก่อนที่จะไป Verify และ Approve เพื่อเข้าร่วม Campaign ต่อไป \r\n\r\n', 0, 0.00, 0.00, 'active', 'Y', 'N', '2020-01-10 18:30:55', 6, '119.76.162.63', NULL, NULL, NULL, NULL, NULL, NULL);
