INSERT INTO `quotations_detail` VALUES (820, 108, 2, 'maintenance coding', '- ตรวจสอบ code ให้ใช้งานได้ปรกติ \r\n- ปรับ code ในส่วนของการเก็บ stamp loop ของการทำงาน\r\n- ปรับโครงสร้างข้อมูลสำหรับเก็บค่า loop ของการทำงาน', 0, 0.00, 0.00, 'active', 'Y', 'N', '2020-08-14 10:19:21', 6, '1.10.209.65', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `quotations_detail` VALUES (821, 108, 3, 'dashboard สรุปผล', '1. สรุปจำนวนรูปที่ทำการไปประมวลผลในแต่ละ loop การทำงาน (ตัวเลข และกราฟ)\r\n2. สรุปจำนวน influencer ที่มีรูปเพิ่มขึ้น / และสรุปจำนวน influencer ที่ไม่ได้ทำการอัพรูปเพิ่มขึ้น\r\n3.  สรุปยอด status influencer [public/private]\r\n4. สรุป keywod ที่พบเจอเยอะที่สุดไล่เรียงลงไปในแต่ละลำดับ (ตัวเลข/กราฟ)\r\n5. สรุปจำนวนรูปในแต่ละ  interest (ตัวเลข/กราฟ)', 0, 0.00, 0.00, 'active', 'Y', 'N', '2020-08-14 10:19:21', 6, '1.10.209.65', NULL, NULL, NULL, NULL, NULL, NULL);
