INSERT INTO `quotations_detail` VALUES (1309, 176, 1, 'Software maintenance ', '- ดูแล ตรวจสอบ แก้ไขข้อผิดผลาดของเว็บไซต์\r\n- ปรับแต่งหน้าเว็บไซด์ตามความต้องการ เช่น เพิ่มเมนู, เพิ่ม section, แก้ไขข้อความ static page\r\n- เพิ่มความสามารถการทำงานของเว็บไซต์ที่แตกต่างจากเดิม เช่น ต้องการเพิ่มช่องทางการชำระเงินเป็น พร้อมเพย์				\r\n- สำรองข้อมูลเว็บไซต์และฐานข้อมูลทุกวัน (01.00 น.)				\r\n- On-page SEO ของทุกหน้า เช่น  Title, description meda data, head tag, image alt tag				\r\n- Software upgrade เช่น PHP version, framework version				\r\n- ให้คำแนะนำปรึกษาด้านเว็บไซต์ \r\n				\r\n* โดยแต่ละเดือนมีชั่วโมงการทำงาน 35 ชั่วโมงต่อเดือน				\r\n', 12, 40000.00, 480000.00, 'active', 'Y', 'N', '2021-09-15 12:10:34', 1, '61.7.156.184', NULL, NULL, NULL, NULL, NULL, NULL);
